{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-b2fb69e6b2d99e2d","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t\n28\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n29\t\n30\tUsage:\n31\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n32\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n33\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n34\t\"\"\"\n35\t\n36\timport argparse\n37\timport os\n38\timport re\n39\timport sys\n40\t\n41\timport yaml\n42\t\n43\tSECTIONS = [(\"Description\", (\"description\",)),\n44\t            (\"Scope\", (\"scope\",)),\n45\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n46\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n47\t\n48\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n49\t\n50\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n51\t           \"repo-onboarding\")\n52\t\n53\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n54\t# way) — parity with the implementation_type_rules judge.\n55\tPARALLEL_PAIRS = {\n56\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n57\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n58\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n59\t}\n60\t\n61\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n62\t\n63\t\n64\tdef read_frontmatter(path):\n65\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n66\t    with open(path, encoding=\"utf-8\") as f:\n67\t        content = f.read()\n68\t    m = FRONTMATTER_RE.match(content)\n69\t    if not m:\n70\t        return {}, content\n71\t    try:\n72\t        data = yaml.safe_load(m.group(1))\n73\t    except yaml.YAMLError:\n74\t        return {}, content\n75\t    if not isinstance(data, dict):\n76\t        return {}, content\n77\t    return data, content[m.end():]\n78\t\n79\t\n80\tdef body_headings(body):\n81\t    heads = []\n82\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n83\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n84\t    return heads\n85\t\n86\t\n87\tdef load_epics(artifacts_dir, strat_id):\n88\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n89\t\n90\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n91\t    \"\"\"\n92\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n93\t    if not os.path.isdir(task_dir):\n94\t        return {}\n95\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n96\t    epics = {}\n97\t    for name in sorted(os.listdir(task_dir)):\n98\t        m = pat.match(name)\n99\t        if not m:\n100\t            continue\n101\t        path = os.path.join(task_dir, name)\n102\t        fm, body = read_frontmatter(path)\n103\t        epics[name[:-3]] = (path, fm, body)\n104\t    return epics\n105\t\n106\t\n107\tdef dependency_closure(start_key, deps):\n108\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n109\t    seen, stack = set(), list(deps.get(start_key, []))\n110\t    while stack:\n111\t        n = stack.pop()\n112\t        if n in seen or n not in deps:\n113\t            continue\n114\t        seen.add(n)\n115\t        stack.extend(deps[n])\n116\t    return seen\n117\t\n118\t\n119\tdef check(strat_id, artifacts_dir, components_path):\n120\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n121\t    probs = []\n122\t    epics = load_epics(artifacts_dir, strat_id)\n123\t    if not epics:\n124\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n125\t                % (strat_id, artifacts_dir)]\n126\t\n127\t    valid_components = set()\n128\t    if os.path.isfile(components_path):\n129\t        with open(components_path, encoding=\"utf-8\") as f:\n130\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n131\t    if not valid_components:\n132\t        probs.append(\"cannot read canonical component list %s — verify the \"\n133\t                     \"path before trusting component names\" % components_path)\n134\t\n135\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n136\t    for key, (path, fm, body) in epics.items():\n137\t        name = key + \".md\"\n138\t        # 1. body sections (contract parity with the artifact judge)\n139\t        heads = body_headings(body)\n140\t        for want, aliases in SECTIONS:\n141\t            if not any(a in h for h in heads for a in aliases):\n142\t                probs.append(\"%s: body missing '%s' section (required \"\n143\t                             \"sections: Description, Scope, Acceptance \"\n144\t                             \"Criteria, HLR Traceability)\" % (name, want))\n145\t        # 2. component vocabulary\n146\t        comp = fm.get(\"component\")\n147\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n148\t                and comp.strip() not in valid_components:\n149\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n150\t                         \"canonical name (submit.py strips unknown names)\"\n151\t                         % (name, comp.strip(), components_path))\n152\t        # collect graph facts\n153\t        dl = fm.get(\"dependencies\")\n154\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n155\t            if isinstance(dl, list) else []\n156\t        is_branch[key] = \"BRANCH-\" in key\n157\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n158\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n159\t        it = fm.get(\"implementation_type\")\n160\t        itype[key] = it if it in IT_ENUM else None\n161\t        prio[key] = fm.get(\"priority\")\n162\t\n163\t    def kind(key):\n164\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n165\t        that is not type Implementation is never a parallel-rule party; an\n166\t        Implementation epic's kind is its implementation_type when that is a\n167\t        known label, else 'general'.\"\"\"\n168\t        if not is_impl[key]:\n169\t            return \"non-implementation\"\n170\t        return itype[key] or \"general\"\n171\t\n172\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n173\t    universe = [k for k in epics\n174\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n175\t    for k in sorted(epics):\n176\t        if not is_docs[k]:\n177\t            continue\n178\t        cl = dependency_closure(k, deps)\n179\t        missing = sorted(e for e in universe if e != k and e not in cl)\n180\t        if missing:\n181\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n182\t                         \"Implementation epic — add %s to its dependency chain\"\n183\t                         % (k, \", \".join(missing)))\n184\t\n185\t    # 4. Priority inheritance — enablers of P0 work must be P0\n186\t    for k in sorted(epics):\n187\t        if is_branch[k] or is_docs[k]:\n188\t            continue\n189\t        if prio.get(k) != \"P0\":\n190\t            continue\n191\t        # every main-plan, non-docs epic in k's closure enables P0 work\n192\t        cl = dependency_closure(k, deps)\n193\t        for t in sorted(cl):\n194\t            if is_branch[t] or is_docs[t]:\n195\t                continue\n196\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n197\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n198\t                             \"but is %s — raise it to P0 or restructure\"\n199\t                             % (t, prio.get(t), k, prio.get(t)))\n200\t\n201\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n202\t    #    pairs carry no dependencies edge in either direction (direct edges\n203\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n204\t    #    them; dependencies naming epics with no file cannot be judged).\n205\t    for k in sorted(epics):\n206\t        if kind(k) == \"docs-authoring\":\n207\t            continue\n208\t        for t in deps[k]:\n209\t            if t not in epics:\n210\t                continue\n211\t            pair = frozenset((kind(t), kind(k)))\n212\t            rule = PARALLEL_PAIRS.get(pair)\n213\t            if rule:\n214\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n215\t                             \"parallel; remove the dependencies edge and \"\n216\t                             \"express any coupling as an AC gate on the \"\n217\t                             \"dependent epic\"\n218\t                             % (rule, t, kind(t), k, kind(k)))\n219\t    return probs\n220\t\n221\t\n222\t# ─── self-check ───────────────────────────────────────────────────────────────\n223\t\n224\tdef _self_check():\n225\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n226\t    import shutil\n227\t    import tempfile\n228\t\n229\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n230\t    try:\n231\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n232\t        os.makedirs(art)\n233\t        comp = os.path.join(tmp, \"components.txt\")\n234\t        with open(comp, \"w\") as f:\n235\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n236\t\n237\t        def write(name, fm, body):\n238\t            with open(os.path.join(art, name), \"w\") as f:\n239\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n240\t\n241\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n242\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n243\t        write(\"RHAISTRAT-9001-E001.md\",\n244\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n245\t              \"dependencies: []\\n\", good_body)\n246\t        write(\"RHAISTRAT-9001-E002.md\",\n247\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n248\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n249\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n250\t              good_body)\n251\t        # a konflux-onboarding epic parallel to the general epic (no edge\n252\t        # either way) is the Rule 10-compliant shape — must not be flagged\n253\t        write(\"RHAISTRAT-9001-E003.md\",\n254\t              \"component: Dashboard\\ntype: Implementation\\n\"\n255\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n256\t              \"dependencies: []\\n\", good_body)\n257\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n258\t                     comp) == [], \"good fixture must pass cleanly\"\n259\t\n260\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n261\t        # Rule 10 konflux-onboarding -> general edge\n262\t        write(\"RHAISTRAT-9002-E001.md\",\n263\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n264\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n265\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n266\t              \"## HLR Traceability\\nh\\n\")\n267\t        write(\"RHAISTRAT-9002-E002.md\",\n268\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n269\t              \"dependencies: []\\n\", good_body)\n270\t        write(\"RHAISTRAT-9002-E003.md\",\n271\t              \"component: Dashboard\\ntype: Implementation\\n\"\n272\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n273\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n274\t        # E004 is a main-plan Implementation the docs epic never depends on\n275\t        write(\"RHAISTRAT-9002-E004.md\",\n276\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n277\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n278\t        write(\"RHAISTRAT-9002-E005.md\",\n279\t              \"component: Dashboard\\ntype: Implementation\\n\"\n280\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n281\t              \"dependencies: []\\n\", good_body)\n282\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n283\t        joined = \"\\n\".join(probs)\n284\t        assert \"missing 'Scope'\" in joined, probs\n285\t        assert \"Model Serving Stack\" in joined, probs\n286\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n287\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n288\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n289\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n290\t        print(\"self-check OK: 5 checks fire on bad fixture, clean on good\")\n291\t        return 0\n292\t    finally:\n293\t        shutil.rmtree(tmp, ignore_errors=True)\n294\t\n295\t\n296\tdef main(argv=None):\n297\t    ap = argparse.ArgumentParser(description=__doc__)\n298\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n299\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n300\t    ap.add_argument(\"--components\",\n301\t                    default=\".context/rhai-components.txt\")\n302\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n303\t    args = ap.parse_args(argv)\n304\t\n305\t    if args.self_check:\n306\t        return _self_check()\n307\t    if not args.strat_id:\n308\t        ap.error(\"strat_id is required (unless --self-check)\")\n309\t\n310\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n311\t    if probs:\n312\t        for p in probs:\n313\t            print(\"VIOLATION: %s\" % p)\n314\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n315\t              \"complete\" % len(probs))\n316\t        return 1\n317\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n318\t    return 0\n319\t\n320\t\n321\tif __name__ == \"__main__\":\n322\t    sys.exit(main())\n323\t"}]},"parent_tool_use_id":"chatcmpl-tool-8dee8d39a363c00d","agent_id":"ae32d1b8c5297bda1","session_id":"2c7f7242-e955-423b-a303-ec17bb0be124","uuid":"a4293181-7922-46e2-b9ff-9855a8f01ac6","timestamp":"2026-10-26T11:25:40.108Z","tool_result_meta":[{"id":"chatcmpl-tool-b2fb69e6b2d99e2d","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Decompose RHAISTRAT-9018 into epics"}
